/// Returns whether the whole input matched, and how many instructions were
/// executed getting to that answer.
pub fn backtrack(prog: &Program, input: &[char]) -> (bool, u64) {
    let mut steps = 0u64;
    let hit = walk(prog, input, 0, 0, &mut steps);
