}

fn walk(prog: &Program, input: &[char], pc: usize, sp: usize, steps: &mut u64) -> bool {
    *steps += 1;
    match prog[pc] {
        Inst::Match => sp == input.len(),
        Inst::Char(c) => {
            sp < input.len() && input[sp] == c && walk(prog, input, pc + 1, sp + 1, steps)
        }
        Inst::Any => sp < input.len() && walk(prog, input, pc + 1, sp + 1, steps),
