                && in_class(negated, &ranges, input[sp])
                && walk(prog, input, pc + 1, sp + 1, steps)
        }
        Inst::Split(a, b) => walk(prog, input, a, sp, steps) || walk(prog, input, b, sp, steps),
        Inst::Jump(t) => walk(prog, input, t, sp, steps),
    }
}

