    Char(char),
    Any,
    Class { negated: bool, ranges: Vec<(char, char)> },
    Split(usize, usize),
    Jump(usize),
    Match,
}

pub type Program = Vec<Inst>;

pub fn compile(ast: &Ast) -> Program {
    let mut prog = Vec::new();
    emit(ast, &mut prog);
    prog.push(Inst::Match);
    prog
}

fn emit(ast: &Ast, prog: &mut Program) {
    match ast {
        Ast::Char(c) => prog.push(Inst::Char(*c)),
        Ast::Dot => prog.push(Inst::Any),
        Ast::Class { negated, ranges } => {
            prog.push(Inst::Class { negated: *negated, ranges: ranges.clone() })
        }
        Ast::Concat(items) => {
            for item in items {
                emit(item, prog);
            }
        }
        Ast::Alternate(a, b) => {
            //     split left, right
            // left:  <a>
            //     jmp after
            // right: <b>
            // after:
            let split = prog.len();
            prog.push(Inst::Split(0, 0));
            emit(a, prog);
            let jump = prog.len();
            prog.push(Inst::Jump(0));
            let right = prog.len();
            emit(b, prog);
            let after = prog.len();
            prog[split] = Inst::Split(split + 1, right);
            prog[jump] = Inst::Jump(after);
        }
        Ast::Star(a) => {
            // split: split body, after
            // body:  <a>
            //        jmp split
            // after:
            let split = prog.len();
            prog.push(Inst::Split(0, 0));
            emit(a, prog);
            prog.push(Inst::Jump(split));
            let after = prog.len();
            prog[split] = Inst::Split(split + 1, after);
        }
        Ast::Plus(a) => {
            // body: <a>
            //       split body, after
            let body = prog.len();
            emit(a, prog);
            let split = prog.len();
            prog.push(Inst::Split(body, split + 1));
        }
        Ast::Optional(a) => {
            let split = prog.len();
            prog.push(Inst::Split(0, 0));
