    for (i, inst) in prog.iter().enumerate() {
        let text = match inst {
            Inst::Char(c) => format!("char {c:?}"),
            Inst::Any => "any".to_string(),
            Inst::Class { negated, ranges } => {
                format!("class {}{:?}", if *negated { "^" } else { "" }, ranges)
            }
            Inst::Split(a, b) => format!("split {a}, {b}"),
            Inst::Jump(t) => format!("jmp {t}"),
